mapper.select:
SELECT
	std.TRADE_ID,
	stdp.PLEDGE_RATIO
FROM
	SETTLE_TRANS_DATA std
LEFT JOIN
	SETTLE_TRANS_DATA_PLEDGE stdp ON std.TRADE_ID = stdp.TRADE_ID
WHERE
	std.CJBH = #{sqcjbh, jdbcType=VARCHAR}
	AND std.SEAT_NUMBER = #{seatNumber, jdbcType=VARCHAR}
	AND std.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
  	AND std.VDATE = #{vdate, jdbcType=DATE}

SELECT
	IS_HOLIDAY
FROM
	VAL_VW_MST_HOLIDAY
WHERE CDATE = #{cdate}
  AND TRADE_CALENDAR_ID = #{calendarId}
